<template><article class="product-card"><router-link :to="`/product/${product.id}`" class="product-image" :style="{background:product.color}"><span class="product-emoji">{{product.emoji}}</span><small>{{product.tag}}</small><button class="heart" @click.prevent="toggle">{{ liked ? '♥' : '♡' }}</button></router-link><div class="product-info"><div class="rating">★★★★★ <span>{{product.rating}}　已售 {{product.sales}}</span></div><router-link :to="`/product/${product.id}`" class="product-name">{{product.name}}</router-link><div class="origin">{{product.origin}}　·　{{product.unit}}</div><div class="price-row"><span class="price">¥{{product.price.toFixed(1)}}</span><del>¥{{product.oldPrice.toFixed(1)}}</del><button class="add" @click="add">+</button></div></div></article></template>
<script setup>import { ref, inject } from 'vue'; import { addToCart, store } from '../data'; const props=defineProps({product:Object}); const notify=inject('notify'); const liked=ref(store.favorites.includes(props.product.id)); const add=()=>{addToCart(props.product.id);notify('已加入购物车')}; const toggle=()=>{liked.value=!liked.value; if(liked.value) store.favorites.push(props.product.id); else store.favorites=store.favorites.filter(id=>id!==props.product.id)}</script>
